// 克制高级 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、camera()（贯穿全片的缓推）、maskText() / maskImage()（遮罩升起入场、向上退出）、tracked()（加字距）、
// hairlineAt() 母题（细线换位、伸缩，强调色圆点停在线端）、veil()（压暗目标以外）、background()、grain()（颗粒）。

const STYLE = {
  color: {
    bg: "#101114", // 带一点暖色相的近黑，不用纯黑
    text: "#ECE9E3",
    muted: "#8A8780",
    hairline: "rgba(236,233,227,0.16)",
    accent: "#FF6A3D", // 唯一强调色，只用在点和短线上
  },
  font: {
    title: '"HarmonyOS Sans SC", "Source Han Sans SC", "Noto Sans SC", "Microsoft YaHei", sans-serif',
    latin: '"Inter", "HarmonyOS Sans", "Segoe UI", sans-serif',
  },
};

// 相邻两段重叠约 0.2 秒：上一段向上退进遮罩时，细线已经滑向下一处，下一段随即升起。
const SCENES = { title: [0, 2.0], keyword: [1.8, 3.7], media: [3.5, 6.3], data: [6.1, 8.2], name: [8.0, 9.6], end: [9.4, 99] };
const COPY = {
  title: "把想法变成画面",
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const expoOut = (v) => (v >= 1 ? 1 : 1 - Math.pow(2, -10 * clamp(v)));
const cubicIn = (v) => clamp(v) ** 3;
const cubicInOut = (v) => { v = clamp(v); return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
const lerp = (a, b, k) => a + (b - a) * k;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 入场 0.8 s expoOut，离场 0.35 s cubicIn；落地后没有新动作，只随 camera() 的缓推走。
function phase(t, [a, b], delay = 0, inDur = 0.8, outDur = 0.35) {
  return { enter: expoOut((t - a - delay) / inDur), leave: cubicIn((t - (b - outDur)) / outDur), on: t >= a && t < b };
}

// 承载运动：整个画面以中心为原点匀速推近，约每秒 1%，从第一帧跑到最后一帧，不起停、不变速。
// 场景之间是细线接力而不是切镜，所以不重置。入场位移叠在它上面，落地后只剩缓推，接点处速度不降到零。
const PUSH = 0.01;
function camera(t, w, h) {
  const s = 1 + PUSH * t;
  return { s, at: (x, y) => [w / 2 + (x - w / 2) * s, h / 2 + (y - h / 2) * s] };
}

// 加字距逐字绘制（拉丁编号用宽字距，中文标题略收紧）。
function tracked(ctx, text, x, y, tracking, align = "left") {
  const chars = [...text];
  const widths = chars.map((c) => ctx.measureText(c).width);
  const total = widths.reduce((s, v) => s + v, 0) + tracking * (chars.length - 1);
  let cx = align === "center" ? x - total / 2 : x;
  chars.forEach((c, i) => { ctx.fillText(c, cx, y); cx += widths[i] + tracking; });
  return total;
}

// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f, tracking = 0) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return [...text].reduce((s, c) => s + measurer.measureText(c).width, 0) + tracking * ([...text].length - 1);
}

// 遮罩上升：文字从一条看不见的基线下方升起，离场时继续向上退出。这是本风格唯一的文字入场方式。
// 做成一层：文字只做竖向位移，再随镜头缩放（pose），运行时据此做运动模糊，遮罩边缘保持锐利。
// 遮罩（clip）是画面坐标里的矩形，每帧按当前时刻的镜头换算，跟着画面一起推近。
// text 可以是随时间变化的函数（例如计数），x 可以是函数（跟随前一段文字的宽度）。
function maskText(w, h, now, { text, x, y, size, f, color, tracking = 0, align = "left", scene, delay = 0, inDur = 0.8, outDur = 0.35, maxWidth }) {
  const width = maxWidth ?? measure(typeof text === "function" ? text(scene[1]) : text, f, tracking);
  const left = align === "center" ? -width / 2 : 0, x0 = typeof x === "function" ? 0 : x;
  const cam = camera(now, w, h), [, top] = cam.at(0, y - size * 1.05), [, bottom] = cam.at(0, y + size * 0.3);
  return {
    clip: [0, top, w, bottom],
    bounds: [x0 + left - size * 0.2, y - size * 1.1, (typeof x === "function" ? w : x0) + left + width + size * 0.2, y + size * 0.35],
    pose: (t) => {
      if (t < scene[0] || t >= scene[1]) return null;
      const p = phase(t, scene, delay, inDur, outDur), c = camera(t, w, h), [ox, oy] = c.at(0, 0);
      return { x: ox, y: oy + c.s * ((1 - p.enter) * size * 1.1 - p.leave * size * 1.1), scale: c.s };
    },
    draw: (ctx, t) => {
      ctx.fillStyle = color;
      ctx.font = f;
      tracked(ctx, typeof text === "function" ? text(t) : text, typeof x === "function" ? x(t) : x, y, tracking, align);
    },
  };
}

// 图片与录屏容器：没有边框、圆角和投影，画面本身就是容器（直角，形状语言只有直线）。
// 和文字同一种入场：画面以自身矩形为遮罩，可见部分从下沿向上揭开，内容同时升起约 1/7 高；
// 离场时继续向上，从上沿退出。遮罩按当前时刻的镜头换算，跟着画面一起推近。
function maskImage(w, h, now, { x, y, iw, ih, scene, delay = 0, inDur = 0.9, outDur = 0.35, draw }) {
  const cam = camera(now, w, h), [l, top] = cam.at(x, y), [r, bottom] = cam.at(x + iw, y + ih);
  const p = phase(now, scene, delay, inDur, outDur), rise = ih * 0.14;
  return {
    clip: [l, bottom - (bottom - top) * p.enter, r, bottom - (bottom - top) * p.leave],
    bounds: [0, 0, iw, ih],
    pose: (t) => {
      if (t < scene[0] + delay || t >= scene[1]) return null;
      const q = phase(t, scene, delay, inDur, outDur), c = camera(t, w, h), [px, py] = c.at(x, y + (1 - q.enter) * rise - q.leave * rise);
      return { x: px, y: py, scale: c.s };
    },
    draw,
  };
}

// 示意画面：一块暖灰调的编辑界面（预览、属性栏、时间线），本地坐标原点在左上角。
// 高亮目标是属性栏里的按钮，范围由 target() 给出，方便细线与压暗对准它。
function mockTarget(iw, ih) { return { x: iw * 0.71, y: ih * 0.5, w: iw * 0.2, h: ih * 0.075 }; }
function mockScreen(ctx, iw, ih, u) {
  ctx.fillStyle = "#212226"; ctx.fillRect(0, 0, iw, ih);
  ctx.fillStyle = "#2A2B30"; ctx.fillRect(0, 0, iw, ih * 0.075);
  for (let i = 0; i < 3; i++) { ctx.fillStyle = "#45464B"; ctx.beginPath(); ctx.arc((16 + i * 14) * u, ih * 0.0375, 3.5 * u, 0, Math.PI * 2); ctx.fill(); }
  // 预览：一张很安静的示意风景，只用暖灰，不用强调色。
  const px = iw * 0.035, py = ih * 0.12, pw = iw * 0.6, ph = ih * 0.55;
  const sky = ctx.createLinearGradient(0, py, 0, py + ph);
  sky.addColorStop(0, "#4A433A"); sky.addColorStop(1, "#2C2B2C");
  ctx.fillStyle = sky; ctx.fillRect(px, py, pw, ph);
  ctx.save(); ctx.beginPath(); ctx.rect(px, py, pw, ph); ctx.clip();
  ctx.fillStyle = "rgba(236,233,227,0.78)"; ctx.beginPath(); ctx.arc(px + pw * 0.68, py + ph * 0.36, ph * 0.09, 0, Math.PI * 2); ctx.fill();
  const hill = (k, color, lift) => {
    ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(px, py + ph);
    for (let i = 0; i <= 10; i++) ctx.lineTo(px + (pw * i) / 10, py + ph * (lift - 0.1 * Math.sin(i * 1.1 + k)));
    ctx.lineTo(px + pw, py + ph); ctx.closePath(); ctx.fill();
  };
  hill(0.4, "#3A3732", 0.7); hill(2.2, "#26262A", 0.86);
  ctx.restore();
  // 属性栏
  const sx = iw * 0.67, sw = iw * 0.29;
  [0.9, 0.55, 0.75, 0.45].forEach((k, i) => { ctx.fillStyle = "#38393E"; ctx.fillRect(sx, py + ih * (0.02 + i * 0.07), sw * k, ih * 0.022); });
  const T = mockTarget(iw, ih);
  ctx.fillStyle = "#4A4A4F"; ctx.fillRect(T.x, T.y, T.w, T.h);
  ctx.fillStyle = "#ECE9E3"; ctx.fillRect(T.x + T.w * 0.22, T.y + T.h * 0.43, T.w * 0.56, T.h * 0.16);
  // 时间线
  const ty = py + ph + ih * 0.07, lanes = [[0, 0.3, 0.32, 0.36], [0.06, 0.48, 0.58, 0.3], [0, 0.22, 0.26, 0.5]];
  lanes.forEach((row, i) => { for (let j = 0; j < row.length; j += 2) { ctx.fillStyle = i === 1 ? "#4A463F" : "#33343A"; ctx.fillRect(px + (iw * 0.93) * row[j], ty + i * ih * 0.055, (iw * 0.93) * row[j + 1], ih * 0.035); } });
}

// 细颗粒：预先生成一张噪点图，每帧换偏移。确定性：只依赖帧序号。
let grainCanvas = null;
function grain(ctx, t, w, h) {
  if (!grainCanvas) {
    grainCanvas = new OffscreenCanvas(1, 1);
    grainCanvas.width = grainCanvas.height = 256;
    const g = grainCanvas.getContext("2d"), img = g.createImageData(256, 256);
    let s = 7;
    for (let i = 0; i < img.data.length; i += 4) {
      s = (s * 16807) % 2147483647;
      const v = (s / 2147483647) * 255;
      img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
      img.data[i + 3] = 255;
    }
    g.putImageData(img, 0, 0);
  }
  const f = Math.floor(t * 24);
  ctx.save();
  ctx.globalAlpha = 0.045;
  ctx.globalCompositeOperation = "overlay";
  ctx.fillStyle = ctx.createPattern(grainCanvas, "repeat");
  ctx.translate((f * 73) % 256, (f * 151) % 256);
  ctx.fillRect(-256, -256, w + 512, h + 512);
  ctx.restore();
}

function background(ctx, w, h) {
  ctx.fillStyle = STYLE.color.bg;
  ctx.fillRect(0, 0, w, h);
  // 左上方一点暖光，四角压暗；都很弱，只为让底色不死板。
  // 渐变两端用同一 RGB 只改透明度：Canvas 按非预乘颜色插值，异色渐隐会出现一圈灰。
  const glow = ctx.createRadialGradient(w * 0.4, h * 0.42, 0, w * 0.4, h * 0.42, w * 0.5);
  glow.addColorStop(0, "rgba(255,244,228,0.05)");
  glow.addColorStop(1, "rgba(255,244,228,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);
  const vignette = ctx.createRadialGradient(w * 0.5, h * 0.5, h * 0.45, w * 0.5, h * 0.5, w * 0.72);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(1, "rgba(0,0,0,0.45)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, w, h);
}

// 母题：一条贯穿全片的细线。每段只改变它的位置和长度（cubicInOut 换位，约 0.4 s），从不消失。
// keys：[时刻, { x, y, len }]，按时间查当前段直接求值。
function hairlineAt(t, keys) {
  let i = 0;
  while (i < keys.length - 1 && t >= keys[i + 1][0]) i++;
  const [ta, a] = keys[i], [tb, b] = keys[Math.min(i + 1, keys.length - 1)];
  const k = tb > ta ? cubicInOut((t - ta) / (tb - ta)) : 1;
  return { x: lerp(a.x, b.x, k), y: lerp(a.y, b.y, k), len: lerp(a.len, b.len, k) };
}

// 一段可伸缩的细线：内容是 100 像素长的线，按长度横向缩放；长度为 0 时不画。
function hairlineLayer(w, h, u, lengthAt, originAt, color) {
  return {
    bounds: [0, 0, 100, Math.max(1, u)],
    pose: (t) => {
      const len = lengthAt(t);
      if (len < 0.5) return null;
      const o = originAt(t), c = camera(t, w, h), [x, y] = c.at(o.x, o.y);
      return { x, y, scaleX: (len / 100) * c.s, scaleY: c.s };
    },
    draw: (ctx) => {
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 100, Math.max(1, u));
    },
  };
}

function layers(_params, w, h, _assets, info) {
  const u = h / 720, x = w * 0.12, C = STYLE.color, F = STYLE.font, out = [];
  const now = info?.time ?? 0;
  const rise = (opts) => maskText(w, h, now, opts);
  // 底：近黑暖底、暖光与压角。像镜头的暗角一样固定在画面上，不随缓推缩放。
  out.push({ draw: (ctx) => background(ctx, w, h) });

  // 标题：不用框，细线就是标题的结构。编号 → 大标题依次从遮罩里升起，细线从左边线向右长出托住标题。
  const title = SCENES.title, titleFont = font(300, 78 * u, F.title), titleW = measure(COPY.title, titleFont, -1.5 * u);
  out.push(rise({ text: "01", x, y: h * 0.38, size: 13 * u, f: font(500, 13 * u, F.latin), color: C.muted, tracking: 3 * u, scene: title, delay: 0.1 }));
  out.push(rise({ text: COPY.title, x: x - 3 * u, y: h * 0.53, size: 78 * u, f: titleFont, color: C.text, tracking: -1.5 * u, scene: title, delay: 0.18 }));

  // 花字与关键词：靠大小和字重拉开层级，不靠颜色。“风格”细而小，“不走样”更大更重；细线滑到“不走样”下方，强调色圆点停在线端。
  const kw = SCENES.keyword, leadFont = font(300, 44 * u, F.title), keyFont = font(400, 104 * u, F.title);
  const leadW = measure(COPY.keyword.lead, leadFont, 2 * u), keyX = x + leadW + 26 * u, keyW = measure(COPY.keyword.key, keyFont, -2 * u), ky = h * 0.57;
  out.push(rise({ text: COPY.keyword.lead, x, y: ky, size: 44 * u, f: leadFont, color: C.text, tracking: 2 * u, scene: kw, delay: 0.2 }));
  out.push(rise({ text: COPY.keyword.key, x: keyX, y: ky, size: 104 * u, f: keyFont, color: C.text, tracking: -2 * u, scene: kw, delay: 0.28 }));

  // 图片与录屏容器 + 高亮：画面从遮罩里升起，细线落在画面下沿当作托线，下方一行小字标明“示意画面”。
  // 高亮：目标以外慢慢压暗，细线换位到目标正下方、缩成目标的宽度，圆点停在线端。不加框、不推镜头。
  const media = SCENES.media, iw = w * 0.56, ih = iw * 9 / 16, ix = x, iy = h * 0.17, T = mockTarget(iw, ih);
  const hlAt = media[0] + 1.2, hl = (t) => cubicInOut((t - hlAt) / 0.7) * (1 - phase(t, media).leave);
  const image = maskImage(w, h, now, { x: ix, y: iy, iw, ih, scene: media, delay: 0.05, draw: (ctx) => mockScreen(ctx, iw, ih, u) });
  out.push(image);
  out.push({
    clip: image.clip, bounds: image.bounds,
    pose: (t) => { const k = hl(t), p = image.pose(t); return p && k > 0.002 ? { ...p, opacity: k } : null; },
    draw: (ctx) => {
      ctx.beginPath(); ctx.rect(0, 0, iw, ih); ctx.rect(T.x - 6 * u, T.y - 6 * u, T.w + 12 * u, T.h + 12 * u);
      ctx.fillStyle = "rgba(16,17,20,0.5)"; ctx.fill("evenodd");
    },
  });
  out.push(rise({ text: COPY.media, x, y: iy + ih + 52 * u, size: 14 * u, f: font(400, 14 * u, F.title), color: C.muted, tracking: 2 * u, scene: media, delay: 0.35 }));

  // 数据：巨大的细数字计数升起，单位跟在数字后面；说明靠右。
  const data = SCENES.data, numFont = font(200, 220 * u, F.latin);
  const count = (t) => COPY.data.value * expoOut((t - data[0] - 0.2) / 1.3);
  const numText = (t) => String(Math.round(count(t)));
  const numWidth = (t) => measure(numText(t), numFont, -8 * u);
  out.push(rise({ text: numText, x: x - 10 * u, y: h * 0.6, size: 220 * u, f: numFont, color: C.text, tracking: -8 * u, scene: data, delay: 0.15, maxWidth: measure("88", numFont, -8 * u) }));
  out.push(rise({ text: COPY.data.unit, x: (t) => x - 10 * u + numWidth(t) + 16 * u, y: h * 0.6 - 120 * u, size: 48 * u, f: font(300, 48 * u, F.latin), color: C.text, scene: data, delay: 0.15, maxWidth: 40 * u }));
  out.push(rise({ text: COPY.data.label, x: w * 0.88 - 86 * u, y: h * 0.6, size: 17 * u, f: font(400, 17 * u, F.title), color: C.muted, tracking: 1.5 * u, scene: data, delay: 0.3 }));

  // 人名条：名字与职位同一行升起，细线缩短托在下方。
  const name = SCENES.name, nameFont = font(500, 28 * u, F.title), nameW = measure(COPY.name.name, nameFont, 4 * u);
  out.push(rise({ text: COPY.name.name, x, y: h * 0.8, size: 28 * u, f: nameFont, color: C.text, tracking: 4 * u, scene: name, delay: 0.25, inDur: 0.7 }));
  out.push(rise({ text: COPY.name.role, x: x + nameW + 28 * u, y: h * 0.8, size: 16 * u, f: font(400, 16 * u, F.title), color: C.muted, tracking: 2 * u, scene: name, delay: 0.33, inDur: 0.7 }));

  // 收尾：一句话居中升起，细线缩短停在下方。
  out.push(rise({ text: COPY.end, x: w / 2, y: h * 0.53, size: 40 * u, f: font(300, 40 * u, F.title), color: C.text, tracking: 6 * u, align: "center", scene: SCENES.end, delay: 0.3, inDur: 0.9 }));

  // 母题细线：每段只换位置和长度。数据段里叠一段亮色进度；强调色圆点停在线端（或进度端）。
  const keys = [
    [0.0, { x, y: h * 0.6, len: 0 }],
    [0.35, { x, y: h * 0.6, len: titleW + 3 * u }],
    [1.85, { x, y: h * 0.6, len: titleW + 3 * u }],
    [2.25, { x: keyX, y: ky + 28 * u, len: keyW }],
    [3.55, { x: keyX, y: ky + 28 * u, len: keyW }],
    [3.95, { x: ix, y: iy + ih + 22 * u, len: iw }],
    [hlAt, { x: ix, y: iy + ih + 22 * u, len: iw }],
    [hlAt + 0.5, { x: ix + T.x, y: iy + T.y + T.h + 12 * u, len: T.w }],
    [6.1, { x: ix + T.x, y: iy + T.y + T.h + 12 * u, len: T.w }],
    [6.5, { x, y: h * 0.7, len: w * 0.76 }],
    [8.0, { x, y: h * 0.7, len: w * 0.76 }],
    [8.4, { x, y: h * 0.835, len: w * 0.2 }],
    [9.4, { x, y: h * 0.835, len: w * 0.2 }],
    [9.8, { x: w * 0.44, y: h * 0.6, len: w * 0.12 }],
  ];
  const line = (t) => hairlineAt(t, keys);
  const progress = (t) => (t >= data[0] && t < data[1] ? count(t) / 100 : null);
  out.push(hairlineLayer(w, h, u, (t) => line(t).len, line, C.hairline));
  out.push(hairlineLayer(w, h, u, (t) => { const p = progress(t); return p == null ? 0 : line(t).len * p; }, line, C.text));
  out.push({
    bounds: [-3.5 * u, -3.5 * u, 3.5 * u, 3.5 * u],
    pose: (t) => {
      const l = line(t), p = progress(t), c = camera(t, w, h);
      if (l.len <= 2) return null;
      const [px, py] = c.at(l.x + (p == null ? l.len : l.len * p), l.y + 0.5 * u);
      return { x: px, y: py, scale: c.s };
    },
    draw: (ctx) => {
      ctx.fillStyle = C.accent;
      ctx.beginPath();
      ctx.arc(0, 0, 3 * u, 0, Math.PI * 2);
      ctx.fill();
    },
  });

  // 最上面一层细颗粒。
  out.push({ draw: (ctx, t) => grain(ctx, t, w, h) });
  return out;
}

